16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.BusinessDays;
20	import org.springframework.samples.petclinic.util.Soundex;
21	
22	import jakarta.persistence.*;
23	import jakarta.validation.constraints.Email;
24	import jakarta.validation.constraints.NotEmpty;
25	import jakarta.validation.constraints.Pattern;
26	
27	import java.nio.charset.StandardCharsets;
28	import java.security.MessageDigest;
29	import java.security.NoSuchAlgorithmException;
30	import java.time.LocalDate;
31	import java.util.*;
32	
33	/**
34	 * Simple JavaBean domain object representing an owner.
35	 *
36	 * @author Ken Krebs
37	 * @author Juergen Hoeller
38	 * @author Sam Brannen
39	 * @author Michael Isvy
40	 */
41	@Entity
42	@Table(name = "owners")
43	public class Owner extends Person {
44	    @Column(name = "address")
45	    @NotEmpty
46	    private String address;
47	
48	    @Column(name = "address_line1")
49	    private String addressLine1;
50	
51	    @Column(name = "address_line2")
52	    private String addressLine2;
53	
54	    @Column(name = "title")
55	    private String title;
56	
57	    @Column(name = "city")
58	    @NotEmpty
59	    private String city;
60	
61	    @Column(name = "telephone")
62	    @NotEmpty
63	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
64	    private String telephone;
65	
66	    @Column(name = "email")
67	    @Email
68	    private String email;
69	
70	    @Column(name = "postcode")
71	    private String postcode;
72	
73	    @Column(name = "registration_date")
74	    private LocalDate registrationDate;
75	
76	    @Column(name = "birth_date")
77	    private LocalDate birthDate;
78	
79	    @Column(name = "customer_code")
80	    private String customerCode;
81	
82	    @Column(name = "namesake_count")
83	    private Integer namesakeCount;
84	
85	    @Column(name = "bulk_signup_warning")
86	    private Boolean bulkSignupWarning;
87	
88	    @Column(name = "capacity_warning")
89	    private Boolean capacityWarning;
90	
91	    @Column(name = "possible_duplicate")
92	    private Boolean possibleDuplicate;
93	
94	    @Column(name = "possible_duplicate_of")
95	    private Integer possibleDuplicateOf;
96	
97	    @Column(name = "membership_level_cap")
98	    private Integer membershipLevelCap;
99	
100	    @Column(name = "deleted")
101	    private boolean deleted;
102	
103	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
104	    private Set<Pet> pets;
105	
106	    public String getAddress() {
107	        return this.address;
108	    }
109	
110	    public void setAddress(String address) {
111	        this.address = address;
112	    }
113	
114	    public String getAddressLine1() {
115	        return this.addressLine1;
116	    }
117	
118	    public void setAddressLine1(String addressLine1) {
119	        this.addressLine1 = addressLine1;
120	    }
121	
122	    public String getAddressLine2() {
123	        return this.addressLine2;
124	    }
125	
126	    public void setAddressLine2(String addressLine2) {
127	        this.addressLine2 = addressLine2;
128	    }
129	
130	    public String getTitle() {
131	        return this.title;
132	    }
133	
134	    public void setTitle(String title) {
135	        this.title = title;
136	    }
137	
138	    public String getCity() {
139	        return this.city;
140	    }
141	
142	    public void setCity(String city) {
143	        this.city = city;
144	    }
145	
146	    public String getTelephone() {
147	        return this.telephone;
148	    }
149	
150	    public void setTelephone(String telephone) {
151	        this.telephone = telephone;
152	    }
153	
154	    public String getEmail() {
155	        return this.email;
156	    }
157	
158	    public void setEmail(String email) {
159	        this.email = email;
160	    }
161	
162	    public String getPostcode() {
163	        return this.postcode;
164	    }
165	
166	    public void setPostcode(String postcode) {
167	        this.postcode = postcode;
168	    }
169	
170	    public LocalDate getRegistrationDate() {
171	        return this.registrationDate;
172	    }
173	
174	    public void setRegistrationDate(LocalDate registrationDate) {
175	        this.registrationDate = registrationDate;
176	    }
177	
178	    public LocalDate getBirthDate() {
179	        return this.birthDate;
180	    }
181	
182	    public void setBirthDate(LocalDate birthDate) {
183	        this.birthDate = birthDate;
184	    }
185	
186	    public String getCustomerCode() {
187	        return this.customerCode;
188	    }
189	
190	    public void setCustomerCode(String customerCode) {
191	        this.customerCode = customerCode;
192	    }
193	
194	    /**
195	     * The owner's current primary identifier, i.e. whatever external reference presently identifies
196	     * this owner as a member. Today that is the {@link #getCustomerCode() customerCode}; when the
197	     * customerCode is later unified into the memberId this method should return the memberId instead.
198	     * Reading the identifier through this single accessor lets callers track whichever identifier is
199	     * current across that migration without changing at their call site.
200	     */
201	    @Transient
202	    public String getPrimaryIdentifier() {
203	        return getCustomerCode();
204	    }
205	
206	    public Integer getNamesakeCount() {
207	        return this.namesakeCount;
208	    }
209	
210	    public void setNamesakeCount(Integer namesakeCount) {
211	        this.namesakeCount = namesakeCount;
212	    }
213	
214	    public Boolean getBulkSignupWarning() {
215	        return this.bulkSignupWarning;
216	    }
217	
218	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
219	        this.bulkSignupWarning = bulkSignupWarning;
220	    }
221	
222	    public Boolean getCapacityWarning() {
223	        return this.capacityWarning;
224	    }
225	
226	    public void setCapacityWarning(Boolean capacityWarning) {
227	        this.capacityWarning = capacityWarning;
228	    }
229	
230	    public Boolean getPossibleDuplicate() {
231	        return this.possibleDuplicate;
232	    }
233	
234	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
235	        this.possibleDuplicate = possibleDuplicate;
236	    }
237	
238	    public Integer getPossibleDuplicateOf() {
239	        return this.possibleDuplicateOf;
240	    }
241	
242	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
243	        this.possibleDuplicateOf = possibleDuplicateOf;
244	    }
245	
246	    /**
247	     * The ceiling applied to this owner's derived membership level, or {@code null} when no cap
248	     * applies. Set on create from the owner's household: a new owner's membership level may not
249	     * exceed one above the current maximum level among its existing household members, so the cap
250	     * is {@code (that maximum) + 1}. With no existing household member the cap is {@code null} and
251	     * the level is used uncapped. See {@link org.springframework.samples.petclinic.mapper.OwnerMapper#formatMembershipLevel}.
252	     */
253	    public Integer getMembershipLevelCap() {
254	        return this.membershipLevelCap;
255	    }
256	
257	    public void setMembershipLevelCap(Integer membershipLevelCap) {
258	        this.membershipLevelCap = membershipLevelCap;
259	    }
260	
261	    public boolean isDeleted() {
262	        return this.deleted;
263	    }
264	
265	    public void setDeleted(boolean deleted) {
266	        this.deleted = deleted;
267	    }
268	
269	    /**
270	     * When no registration date is supplied, default it to the server's current date, then roll
271	     * the effective date forward onto a business day: a Saturday or Sunday becomes the following
272	     * Monday. Running on {@link PrePersist} keeps both invariants true for every create path
273	     * (any controller, bulk import or test fixture) rather than a single entry point. The roll is
274	     * idempotent, so a date already adjusted by a caller is left unchanged.
275	     */
276	    @PrePersist
277	    protected void onCreate() {
278	        this.registrationDate = BusinessDays.effectiveRegistrationDate(this.registrationDate);
279	    }
280	
281	    /**
282	     * The single derived key behind all duplicate detection: the lower-case hex SHA-256 (64 hex
283	     * characters) of {@code <normalizedTelephone>|<lowerEmail>|<soundex(lastName)>}, where the
284	     * telephone is the stored (normalized) value or an empty string when absent, the email is
285	     * lower-cased or an empty string when absent, and the surname component is the standard Soundex
286	     * code of the last name (see {@link org.springframework.samples.petclinic.util.Soundex}).
287	     * Because the telephone is part of the key, two owners are duplicates only when their WHOLE
288	     * identity keys are equal; two owners sharing a surname (hence Soundex) and postcode but with
289	     * different telephones have different identity keys and are therefore both allowed, surfacing
290	     * instead as a soft possible-duplicate match.
291	     */
292	    @Transient
293	    public String getIdentityKey() {
294	        String telephone = this.telephone == null ? "" : this.telephone;
295	        String email = this.email == null ? "" : this.email.toLowerCase();
296	        String key = telephone + "|" + email + "|" + Soundex.encode(getLastName());
297	        return sha256Hex(key, 32);
298	    }
299	
300	    /**
301	     * The deterministic household identifier derived from the owner's own fields, mirroring
302	     * {@link #getIdentityKey()}: the first twelve lower-case hex characters (the first six bytes)
303	     * of the SHA-256 of {@code <normalizedLastName>|<postcode>}, where the last name is normalized
304	     * by trimming, collapsing internal whitespace and lower-casing, and an absent postcode counts
305	     * as empty. Because it is a pure function of the stored last name and postcode, every owner
306	     * sharing both automatically carries the same value, with no linking step or stored column.
307	     */
308	    @Transient
309	    public String getHouseholdId() {
310	        String lastName = getLastName() == null ? ""
311	            : getLastName().trim().replaceAll("\\s+", " ").toLowerCase();
312	        String key = lastName + "|" + (this.postcode == null ? "" : this.postcode);
313	        return sha256Hex(key, 6);
314	    }
315	
316	    /**
317	     * The lower-case hex SHA-256 of {@code value}, truncated to the first {@code bytes} bytes
318	     * (so {@code 2 * bytes} hex characters). Shared by the derived identity and household keys so
319	     * the two stay consistent; they differ only in how many leading bytes they keep.
320	     */
321	    private static String sha256Hex(String value, int bytes) {
322	        try {
323	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
324	            StringBuilder sb = new StringBuilder(bytes * 2);
325	            for (int i = 0; i < bytes; i++) {
326	                sb.append(String.format("%02x", digest[i]));
327	            }
328	            return sb.toString();
329	        }
330	        catch (NoSuchAlgorithmException e) {
331	            throw new IllegalStateException("SHA-256 not available", e);
332	        }
333	    }
334	
335	    protected Set<Pet> getPetsInternal() {
336	        if (this.pets == null) {
337	            this.pets = new HashSet<>();
338	        }
339	        return this.pets;
340	    }
341	
342	    protected void setPetsInternal(Set<Pet> pets) {
343	        this.pets = pets;
344	    }
345	
346	    public List<Pet> getPets() {
347	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
348	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
349	        return Collections.unmodifiableList(sortedPets);
350	    }
351	
352	    public void setPets(List<Pet> pets) {
353	        this.pets = new HashSet<>(pets);
354	    }
355	
356	    public void addPet(Pet pet) {
357	        getPetsInternal().add(pet);
358	        pet.setOwner(this);
359	    }
360	
361	    /**
362	     * Return the Pet with the given name, or null if none found for this Owner.
363	     *
364	     * @param name to test
365	     * @return true if pet name is already in use
366	     */
367	    public Pet getPet(String name) {
368	        return getPet(name, false);
369	    }
370	
371	    /**
372	     * Return the Pet with the given name, or null if none found for this Owner.
373	     *
374	     * @param name to test
375	     * @return true if pet name is already in use
376	     */
377	    public Pet getPet(String name, boolean ignoreNew) {
378	        name = name.toLowerCase();
379	        for (Pet pet : getPetsInternal()) {
380	            if (!ignoreNew || !pet.isNew()) {
381	                String compName = pet.getName();
382	                compName = compName.toLowerCase();
383	                if (compName.equals(name)) {
384	                    return pet;
385	                }
386	            }
387	        }
388	        return null;
389	    }
390	
391	    public Pet getPet(Integer petId) {
392	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
393	    }
394	
395	    @Override
396	    public String toString() {
397	        return new ToStringCreator(this)
398	
399	            .append("id", this.getId())
400	            .append("new", this.isNew())
401	            .append("lastName", this.getLastName())
402	            .append("firstName", this.getFirstName())
403	            .append("address", this.address)
404	            .append("addressLine1", this.addressLine1)
405	            .append("addressLine2", this.addressLine2)
406	            .append("city", this.city)
407	            .append("telephone", this.telephone)
408	            .append("email", this.email)
409	            .append("postcode", this.postcode)
410	            .append("registrationDate", this.registrationDate)
411	            .append("birthDate", this.birthDate)
412	            .append("customerCode", this.customerCode)
413	            .append("householdId", this.getHouseholdId())
414	            .append("namesakeCount", this.namesakeCount)
415	            .append("bulkSignupWarning", this.bulkSignupWarning)
416	            .append("capacityWarning", this.capacityWarning)
417	            .append("possibleDuplicate", this.possibleDuplicate)
418	            .append("possibleDuplicateOf", this.possibleDuplicateOf)
419	            .append("membershipLevelCap", this.membershipLevelCap)
420	            .append("deleted", this.deleted)
421	            .toString();
422	    }
423	}
