package org.springframework.samples.petclinic.model;

import org.springframework.core.style.ToStringCreator;
import org.springframework.samples.petclinic.util.BusinessDays;
import org.springframework.samples.petclinic.util.Soundex;

import jakarta.persistence.*;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Pattern;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.LocalDate;
import java.util.*;

/**
 * Simple JavaBean domain object representing an owner.
 *
 * @author Ken Krebs
 * @author Juergen Hoeller
 * @author Sam Brannen
 * @author Michael Isvy
 */
@Entity
@Table(name = "owners")
public class Owner extends Person {
    @Column(name = "address")
    @NotEmpty
    private String address;

    @Column(name = "address_line1")
    private String addressLine1;

    @Column(name = "address_line2")
    private String addressLine2;

    @Column(name = "title")
    private String title;

    @Column(name = "city")
    @NotEmpty
    private String city;

    @Column(name = "telephone")
    @NotEmpty
    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
    private String telephone;

    @Column(name = "email")
    @Email
    private String email;

    @Column(name = "postcode")
    private String postcode;

    @Column(name = "registration_date")
    private LocalDate registrationDate;

    @Column(name = "birth_date")
    private LocalDate birthDate;

    @Column(name = "customer_code")
    private String customerCode;

    @Column(name = "namesake_count")
    private Integer namesakeCount;

    @Column(name = "bulk_signup_warning")
    private Boolean bulkSignupWarning;

    @Column(name = "capacity_warning")
    private Boolean capacityWarning;

    @Column(name = "possible_duplicate")
    private Boolean possibleDuplicate;

    @Column(name = "possible_duplicate_of")
    private Integer possibleDuplicateOf;

    @Column(name = "membership_level_cap")
    private Integer membershipLevelCap;

    @Column(name = "deleted")
    private boolean deleted;

    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
    private Set<Pet> pets;

    public String getAddress() {
        return this.address;
    }

    public void setAddress(String address) {
        this.address = address;
    }

    public String getAddressLine1() {
        return this.addressLine1;
    }

    public void setAddressLine1(String addressLine1) {
        this.addressLine1 = addressLine1;
    }

    public String getAddressLine2() {
        return this.addressLine2;
    }

    public void setAddressLine2(String addressLine2) {
        this.addressLine2 = addressLine2;
    }

    public String getTitle() {
        return this.title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getCity() {
        return this.city;
    }

    public void setCity(String city) {
        this.city = city;
    }

    public String getTelephone() {
        return this.telephone;
    }

    public void setTelephone(String telephone) {
        this.telephone = telephone;
    }

    public String getEmail() {
        return this.email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public String getPostcode() {
        return this.postcode;
    }

    public void setPostcode(String postcode) {
        this.postcode = postcode;
    }

    public LocalDate getRegistrationDate() {
        return this.registrationDate;
    }

    public void setRegistrationDate(LocalDate registrationDate) {
        this.registrationDate = registrationDate;
    }

    public LocalDate getBirthDate() {
        return this.birthDate;
    }

    public void setBirthDate(LocalDate birthDate) {
        this.birthDate = birthDate;
    }

    public String getCustomerCode() {
        return this.customerCode;
    }

    public void setCustomerCode(String customerCode) {
        this.customerCode = customerCode;
    }

    /**
     * The owner's current primary identifier, i.e. whatever external reference presently identifies
     * this owner as a member. Today that is the {@link #getCustomerCode() customerCode}; when the
     * customerCode is later unified into the memberId this method should return the memberId instead.
     * Reading the identifier through this single accessor lets callers track whichever identifier is
     * current across that migration without changing at their call site.
     */
    @Transient
    public String getPrimaryIdentifier() {
        return getCustomerCode();
    }

    public Integer getNamesakeCount() {
        return this.namesakeCount;
    }

    public void setNamesakeCount(Integer namesakeCount) {
        this.namesakeCount = namesakeCount;
    }

    public Boolean getBulkSignupWarning() {
        return this.bulkSignupWarning;
    }

    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
        this.bulkSignupWarning = bulkSignupWarning;
    }

    public Boolean getCapacityWarning() {
        return this.capacityWarning;
    }

    public void setCapacityWarning(Boolean capacityWarning) {
        this.capacityWarning = capacityWarning;
    }

    public Boolean getPossibleDuplicate() {
        return this.possibleDuplicate;
    }

    public void setPossibleDuplicate(Boolean possibleDuplicate) {
        this.possibleDuplicate = possibleDuplicate;
    }

    public Integer getPossibleDuplicateOf() {
        return this.possibleDuplicateOf;
    }

    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
        this.possibleDuplicateOf = possibleDuplicateOf;
    }

    /**
     * The ceiling applied to this owner's derived membership level, or {@code null} when no cap
     * applies. Set on create from the owner's household: a new owner's membership level may not
     * exceed one above the current maximum level among its existing household members, so the cap
     * is {@code (that maximum) + 1}. With no existing household member the cap is {@code null} and
     * the level is used uncapped. See {@link org.springframework.samples.petclinic.mapper.OwnerMapper#formatMembershipLevel}.
     */
    public Integer getMembershipLevelCap() {
        return this.membershipLevelCap;
    }

    public void setMembershipLevelCap(Integer membershipLevelCap) {
        this.membershipLevelCap = membershipLevelCap;
    }

    public boolean isDeleted() {
        return this.deleted;
    }

    public void setDeleted(boolean deleted) {
        this.deleted = deleted;
    }

    /**
     * When no registration date is supplied, default it to the server's current date, then roll
     * the effective date forward onto a business day: a Saturday or Sunday becomes the following
     * Monday. Running on {@link PrePersist} keeps both invariants true for every create path
     * (any controller, bulk import or test fixture) rather than a single entry point. The roll is
     * idempotent, so a date already adjusted by a caller is left unchanged.
     */
    @PrePersist
    protected void onCreate() {
        this.registrationDate = BusinessDays.effectiveRegistrationDate(this.registrationDate);
    }

    /**
     * The single derived key behind all duplicate detection: the lower-case hex SHA-256 (64 hex
     * characters) of {@code <normalizedTelephone>|<lowerEmail>|<soundex(lastName)>}, where the
     * telephone is the stored (normalized) value or an empty string when absent, the email is
     * lower-cased or an empty string when absent, and the surname component is the standard Soundex
     * code of the last name (see {@link org.springframework.samples.petclinic.util.Soundex}).
     * Because the telephone is part of the key, two owners are duplicates only when their WHOLE
     * identity keys are equal; two owners sharing a surname (hence Soundex) and postcode but with
     * different telephones have different identity keys and are therefore both allowed, surfacing
     * instead as a soft possible-duplicate match.
     */
    @Transient
    public String getIdentityKey() {
        String telephone = this.telephone == null ? "" : this.telephone;
        String email = this.email == null ? "" : this.email.toLowerCase();
        String key = telephone + "|" + email + "|" + Soundex.encode(getLastName());
        return sha256Hex(key, 32);
    }

    /**
     * The deterministic household identifier derived from the owner's own fields, mirroring
     * {@link #getIdentityKey()}: the first twelve lower-case hex characters (the first six bytes)
     * of the SHA-256 of {@code <normalizedLastName>|<postcode>}, where the last name is normalized
     * by trimming, collapsing internal whitespace and lower-casing, and an absent postcode counts
     * as empty. Because it is a pure function of the stored last name and postcode, every owner
     * sharing both automatically carries the same value, with no linking step or stored column.
     */
    @Transient
    public String getHouseholdId() {
        String lastName = getLastName() == null ? ""
            : getLastName().trim().replaceAll("\\s+", " ").toLowerCase();
        String key = lastName + "|" + (this.postcode == null ? "" : this.postcode);
        return sha256Hex(key, 6);
    }

    /**
     * The lower-case hex SHA-256 of {@code value}, truncated to the first {@code bytes} bytes
     * (so {@code 2 * bytes} hex characters). Shared by the derived identity and household keys so
     * the two stay consistent; they differ only in how many leading bytes they keep.
     */
    private static String sha256Hex(String value, int bytes) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(bytes * 2);
            for (int i = 0; i < bytes; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    protected Set<Pet> getPetsInternal() {
        if (this.pets == null) {
            this.pets = new HashSet<>();
        }
        return this.pets;
    }

    protected void setPetsInternal(Set<Pet> pets) {
        this.pets = pets;
    }

    public List<Pet> getPets() {
        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
        return Collections.unmodifiableList(sortedPets);
    }

    public void setPets(List<Pet> pets) {
        this.pets = new HashSet<>(pets);
    }

    public void addPet(Pet pet) {
        getPetsInternal().add(pet);
        pet.setOwner(this);
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name to test
     * @return true if pet name is already in use
     */
    public Pet getPet(String name) {
        return getPet(name, false);
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name to test
     * @return true if pet name is already in use
     */
    public Pet getPet(String name, boolean ignoreNew) {
        name = name.toLowerCase();
        for (Pet pet : getPetsInternal()) {
            if (!ignoreNew || !pet.isNew()) {
                String compName = pet.getName();
                compName = compName.toLowerCase();
                if (compName.equals(name)) {
                    return pet;
                }
            }
        }
        return null;
    }

    public Pet getPet(Integer petId) {
        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
    }

    @Override
    public String toString() {
        return new ToStringCreator(this)

            .append("id", this.getId())
            .append("new", this.isNew())
            .append("lastName", this.getLastName())
            .append("firstName", this.getFirstName())
            .append("address", this.address)
            .append("addressLine1", this.addressLine1)
            .append("addressLine2", this.addressLine2)
            .append("city", this.city)
            .append("telephone", this.telephone)
            .append("email", this.email)
            .append("postcode", this.postcode)
            .append("registrationDate", this.registrationDate)
            .append("birthDate", this.birthDate)
            .append("customerCode", this.customerCode)
            .append("householdId", this.getHouseholdId())
            .append("namesakeCount", this.namesakeCount)
            .append("bulkSignupWarning", this.bulkSignupWarning)
            .append("capacityWarning", this.capacityWarning)
            .append("possibleDuplicate", this.possibleDuplicate)
            .append("possibleDuplicateOf", this.possibleDuplicateOf)
            .append("membershipLevelCap", this.membershipLevelCap)
            .append("deleted", this.deleted)
            .toString();
    }
}

