1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.rest.validation.E164Telephone;
13	import org.springframework.samples.petclinic.util.AddressNormalizer;
14	import org.springframework.samples.petclinic.util.Regions;
15	
16	import java.time.LocalDate;
17	import java.util.Collection;
18	import java.util.List;
19	
20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "selfLink", expression = "java(formatSelfLink(owner))")
27	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
28	    @Mapping(target = "salutation", expression = "java(formatSalutation(owner))")
29	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
30	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
31	    @Mapping(target = "checkDigit", expression = "java(formatCheckDigit(owner))")
32	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
33	    @Mapping(target = "fiscalYear", expression = "java(formatFiscalYear(owner))")
34	    @Mapping(target = "membershipPoints", expression = "java(formatMembershipPoints(owner))")
35	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
36	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
37	    @Mapping(target = "timezone", expression = "java(formatTimezone(owner))")
38	    @Mapping(target = "bulkSignupWarning", expression = "java(formatBulkSignupWarning(owner))")
39	    @Mapping(target = "capacityWarning", expression = "java(formatCapacityWarning(owner))")
40	    @Mapping(target = "possibleDuplicate", expression = "java(formatPossibleDuplicate(owner))")
41	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
42	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
43	    OwnerDto toOwnerDto(Owner owner);
44	
45	    /**
46	     * Resolve an owner's possible-duplicate flag, coalescing a {@code null} stored value
47	     * (e.g. for owners created before the flag existed) to {@code false} so the response
48	     * always carries an explicit boolean.
49	     */
50	    default Boolean formatPossibleDuplicate(Owner owner) {
51	        if (owner == null) {
52	            return null;
53	        }
54	        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
55	    }
56	
57	    /**
58	     * Derive an owner's age band from its {@code birthDate}, measured as the owner's age in whole
59	     * years on its {@code registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18
60	     * through 64, and {@code "SENIOR"} at 65 and over. Returns {@code null} when the owner, its
61	     * birth date or its registration date is absent, since the band cannot be derived without both
62	     * dates.
63	     */
64	    default String formatAgeBand(Owner owner) {
65	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
66	            return null;
67	        }
68	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
69	        if (age < 18) {
70	            return "MINOR";
71	        }
72	        if (age < 65) {
73	            return "ADULT";
74	        }
75	        return "SENIOR";
76	    }
77	
78	    /**
79	     * Derive an owner's preferred contact channel from its stored contact details:
80	     * {@code "EMAIL"} when a (non-blank) email address is present, otherwise {@code "PHONE"}.
81	     */
82	    default String formatContactPreference(Owner owner) {
83	        if (owner == null) {
84	            return null;
85	        }
86	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
87	        return hasEmail ? "EMAIL" : "PHONE";
88	    }
89	
90	    /**
91	     * Resolve an owner's bulk-signup warning flag, coalescing a {@code null} stored value
92	     * (e.g. for owners created before the flag existed) to {@code false} so the response
93	     * always carries an explicit boolean.
94	     */
95	    default Boolean formatBulkSignupWarning(Owner owner) {
96	        if (owner == null) {
97	            return null;
98	        }
99	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
100	    }
101	
102	    /**
103	     * Resolve an owner's capacity-warning flag, coalescing a {@code null} stored value
104	     * (e.g. for owners created before the flag existed) to {@code false} so the response
105	     * always carries an explicit boolean.
106	     */
107	    default Boolean formatCapacityWarning(Owner owner) {
108	        if (owner == null) {
109	            return null;
110	        }
111	        return Boolean.TRUE.equals(owner.getCapacityWarning());
112	    }
113	
114	    /**
115	     * Derive an owner's locality from its region-and-hash identity: the {@code <REGION>} segment
116	     * of the {@code customerCode} (the part before the first hyphen), which is the region code
117	     * derived from the owner's postcode. For an owner that has not yet been assigned a customer
118	     * code, the region is derived directly from the postcode (see {@link Regions#forPostcode}),
119	     * yielding the same value the code would carry. Returns {@code null} only when the owner
120	     * itself is {@code null}.
121	     */
122	    default String formatLocality(Owner owner) {
123	        if (owner == null) {
124	            return null;
125	        }
126	        String code = owner.getCustomerCode();
127	        if (code != null) {
128	            int hyphen = code.indexOf('-');
129	            return hyphen >= 0 ? code.substring(0, hyphen) : code;
130	        }
131	        return Regions.forPostcode(owner.getPostcode());
132	    }
133	
134	    /**
135	     * Derive an owner's timezone as the IANA name mapped from its locality/region via a fixed
136	     * region-to-timezone table (see {@link Regions#timezoneForRegion}): NSW -> Australia/Sydney,
137	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane. Returns {@code null} when the owner
138	     * is {@code null} or its region is not in the table.
139	     */
140	    default String formatTimezone(Owner owner) {
141	        if (owner == null) {
142	            return null;
143	        }
144	        return Regions.timezoneForRegion(formatLocality(owner));
145	    }
146	
147	    /**
148	     * Compute an owner's membership points. Points start at {@code 0} and gain: {@code 2} when an
149	     * email address is present; {@code 1} when the owner has no namesakes (its
150	     * {@code namesakeCount} is {@code 0}); {@code 2} for a household of three or more members (the
151	     * owner plus its pets); and {@code 3} when the owner's tenure (the number of fiscal years
152	     * elapsed since its {@code registrationDate}'s fiscal year) exceeds {@code 1}. A null or absent
153	     * namesake count is treated as not being zero, so it contributes nothing.
154	     */
155	    default Integer formatMembershipPoints(Owner owner) {
156	        if (owner == null) {
157	            return null;
158	        }
159	        int points = 0;
160	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
161	        if (hasEmail) {
162	            points += 2;
163	        }
164	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
165	        if (uniqueName) {
166	            points += 1;
167	        }
168	        int householdSize = 1 + (owner.getPets() == null ? 0 : owner.getPets().size());
169	        if (householdSize >= 3) {
170	            points += 2;
171	        }
172	        LocalDate registrationDate = owner.getRegistrationDate();
173	        if (registrationDate != null
174	            && fiscalYearEndYear(LocalDate.now()) - fiscalYearEndYear(registrationDate) > 1) {
175	            points += 3;
176	        }
177	        return points;
178	    }
179	
180	    /**
181	     * Determine an owner's membership level, a number from {@code 1} to {@code 4} derived from its
182	     * membership points (see {@link #formatMembershipPoints(Owner)}): level {@code 1} for
183	     * {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3}, {@code 3} for {@code 4}-{@code 5}
184	     * and {@code 4} for {@code 6} or more.
185	     *
186	     * <p>The level is then capped by the owner's {@code membershipLevelCap} when one is present (see
187	     * {@link Owner#getMembershipLevelCap()}): a new owner's level may not exceed one above the
188	     * current maximum level among its existing household members, so the returned value is the
189	     * smaller of the points-derived level and the cap. A {@code null} cap means no household ceiling
190	     * applies and the points-derived level is returned unchanged.
191	     */
192	    default Integer formatMembershipLevel(Owner owner) {
193	        if (owner == null) {
194	            return null;
195	        }
196	        int points = formatMembershipPoints(owner);
197	        int level;
198	        if (points <= 1) {
199	            level = 1;
200	        }
201	        else if (points <= 3) {
202	            level = 2;
203	        }
204	        else if (points <= 5) {
205	            level = 3;
206	        }
207	        else {
208	            level = 4;
209	        }
210	        Integer cap = owner.getMembershipLevelCap();
211	        if (cap != null && cap < level) {
212	            return cap;
213	        }
214	        return level;
215	    }
216	
217	    /**
218	     * Compute an owner's check digit: a single Luhn check digit (0-9) over the digits
219	     * contained in the owner's {@code customerCode}. Non-digit characters (the region segment
220	     * and any hex letters of the hash) are ignored. Returns {@code null} when the owner or its
221	     * customer code is absent, since the digit cannot be derived without the code.
222	     */
223	    default Integer formatCheckDigit(Owner owner) {
224	        if (owner == null || owner.getCustomerCode() == null) {
225	            return null;
226	        }
227	        String code = owner.getCustomerCode();
